def variants(cells):
    s=sorted((r-min(r for r,c in cells),c-min(c for r,c in cells)) for r,c in cells)
    res={frozenset(s)}
    cur=s
    for k in range(4):
        cur=sorted((c,-r) for r,c in cur)  # rot90 about origin then normalize handled by key
        break
    # Just use 8 transforms of normalized set: identity,H,V,rot180,T,Tf,Ht
    def t(s): return [(c,-r) for r,c in s]
    def h(s): return [(-c,r) for r,c in s]
    res=frozenset({})
    sset=frozenset(s)
    ss=[sset,t(sset),h(sset),frozenset(t(h(s)))|{}] 
    res|=ss
    res|= {frozenset(h(x)) for x in (sset,t(sset))}
    res|= {frozenset(t(x)) for x in (sset,t(sset),h(sset))}
    return res
