def comps_of(g,c):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==c and not seen[i][j]:
                q=[(i,j)]; seen[i][j]=True; cells=set()
                while q:
                    a,b=q.pop(); cells.add((a,b))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            x,y=a+dx,b+dy
                            if 0<=x<H and 0<=y<W and g[x][y]==c and not seen[x][y]:
                                seen[x][y]=True; q.append((x,y))
                out.append(cells)
    return out
